insert into public.questions (exam_category, subject, topic, type, difficulty, body, body_hi, question_data, options, marks_correct, marks_wrong, explanation, explanation_hi, concept_group_id, source_type, source_citation, status)
values
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','medium','Consider the following statements about India''s securities market:','भारत के प्रतिभूति बाज़ार के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["India moved to T+1 settlement for equity trades in 2023.", "SEBI is a statutory body.", "SEBI regulates the commodity derivatives market."], "statements_hi": ["भारत ने 2023 में इक्विटी सौदों के लिए T+1 निपटान अपना लिया।", "SEBI एक वैधानिक (statutory) निकाय है।", "SEBI कमोडिटी डेरिवेटिव बाज़ार का विनियमन करता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Since January 2023 every listed share settles one working day after the trade, making India one of the first large markets on T+1; an optional same-day (T+0) cycle has since been added for some stocks. SEBI, set up in 1988, got statutory powers under the SEBI Act, 1992, and took over commodity derivatives when the Forward Markets Commission was merged into it in 2015.','तीनों कथन सही हैं। जनवरी 2023 से हर सूचीबद्ध शेयर का निपटान सौदे के एक कार्यदिवस बाद होता है, जिससे भारत T+1 अपनाने वाले पहले बड़े बाज़ारों में से एक बना; तब से कुछ शेयरों के लिए वैकल्पिक उसी दिन (T+0) का चक्र भी जोड़ा गया है। 1988 में बने SEBI को SEBI अधिनियम, 1992 के तहत वैधानिक शक्तियाँ मिलीं, और 2015 में वायदा बाज़ार आयोग के इसमें विलय के बाद इसने कमोडिटी डेरिवेटिव का विनियमन भी सँभाल लिया।','fm-sebi-t-plus-one-commodities','original_pattern_matched','Securities and Exchange Board of India -- circulars on T+1 settlement; SEBI Act, 1992.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','medium','Consider the following statements about public issues of shares:','शेयरों के सार्वजनिक निर्गमों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["In a book-built issue, the issue price is discovered from bids received within a price band.", "Anchor investors are small retail investors who get shares before the issue opens to the public.", "A green-shoe option allows extra shares to be allotted so that the price can be stabilised after listing."], "statements_hi": ["बुक-बिल्ट निर्गम में निर्गम मूल्य एक मूल्य-सीमा (price band) के भीतर मिली बोलियों से तय होता है।", "एंकर निवेशक छोटे खुदरा निवेशक होते हैं, जिन्हें निर्गम जनता के लिए खुलने से पहले शेयर मिलते हैं।", "ग्रीन-शू विकल्प अतिरिक्त शेयर आवंटित करने देता है, ताकि सूचीबद्ध होने के बाद मूल्य को स्थिर किया जा सके।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 3 are correct. Most Indian IPOs use book building, and the green-shoe option lets a stabilising agent buy shares in the market if the price falls below the issue price in the first weeks. Statement 2 is wrong: anchor investors are qualified institutional buyers -- mutual funds, insurers, foreign portfolio investors -- who bid a day before the issue opens and must hold their shares for a lock-in period, signalling confidence to other investors.','कथन 1 और 3 सही हैं। अधिकांश भारतीय IPO बुक-बिल्डिंग का उपयोग करते हैं, और ग्रीन-शू विकल्प एक स्थिरीकरण एजेंट को पहले कुछ सप्ताहों में मूल्य निर्गम मूल्य से नीचे जाने पर बाज़ार से शेयर ख़रीदने देता है। कथन 2 गलत है: एंकर निवेशक योग्य संस्थागत ख़रीदार होते हैं, जैसे म्यूचुअल फ़ंड, बीमा कंपनियाँ और विदेशी पोर्टफ़ोलियो निवेशक, जो निर्गम खुलने से एक दिन पहले बोली लगाते हैं और उन्हें अपने शेयर एक लॉक-इन अवधि तक रखने होते हैं, जिससे दूसरे निवेशकों को भरोसे का संकेत मिलता है।','fm-ipo-book-building-anchor-greenshoe','original_pattern_matched','Securities and Exchange Board of India (Issue of Capital and Disclosure Requirements) Regulations, 2018.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','medium','Consider the following statements about Alternative Investment Funds (AIFs):','वैकल्पिक निवेश कोषों (AIF) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["AIFs are regulated by SEBI.", "Mutual funds are a category of AIF.", "AIFs can raise money from the general public through advertisements, as in a public issue."], "statements_hi": ["AIF का विनियमन SEBI करता है।", "म्यूचुअल फ़ंड AIF की एक श्रेणी हैं।", "AIF सार्वजनिक निर्गम की तरह विज्ञापनों के ज़रिए आम जनता से धन जुटा सकते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: AIFs are privately pooled funds governed by SEBI''s AIF Regulations, 2012, in three categories -- venture capital, SME, social and infrastructure funds in Category I; private equity and debt funds in Category II; and hedge funds in Category III. Statement 2 is wrong: mutual funds are regulated separately and are expressly excluded from the AIF framework. Statement 3 is wrong: AIFs raise money through private placement from sophisticated investors, with a high minimum investment (generally 1 crore rupees), not from the public at large.','केवल कथन 1 सही है: AIF निजी रूप से एकत्र कोष हैं, जिन पर SEBI के AIF विनियम, 2012 लागू होते हैं; इनकी तीन श्रेणियाँ हैं: श्रेणी I में वेंचर कैपिटल, SME, सामाजिक और अवसंरचना कोष; श्रेणी II में प्राइवेट इक्विटी और ऋण कोष; और श्रेणी III में हेज फ़ंड। कथन 2 गलत है: म्यूचुअल फ़ंड अलग से विनियमित होते हैं और AIF ढाँचे से स्पष्ट रूप से बाहर रखे गए हैं। कथन 3 गलत है: AIF आम जनता से नहीं, बल्कि जानकार निवेशकों से निजी नियोजन (private placement) के ज़रिए, ऊँचे न्यूनतम निवेश (सामान्यतः 1 करोड़ रुपये) के साथ, धन जुटाते हैं।','fm-aif-regulation','original_pattern_matched','Securities and Exchange Board of India (Alternative Investment Funds) Regulations, 2012.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','medium','Consider the following statements about REITs and InvITs:','REIT और InvIT के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Real Estate Investment Trusts own income-generating property and must distribute most of their income to unit holders.", "Infrastructure Investment Trusts pool money to invest in projects such as roads and power transmission lines.", "REITs and InvITs are regulated by the RBI."], "statements_hi": ["रियल एस्टेट निवेश ट्रस्ट (REIT) आय देने वाली संपत्तियों के स्वामी होते हैं और उन्हें अपनी अधिकांश आय यूनिट धारकों में बाँटनी होती है।", "अवसंरचना निवेश ट्रस्ट (InvIT) सड़कों और बिजली पारेषण लाइनों जैसी परियोजनाओं में निवेश के लिए धन एकत्र करते हैं।", "REIT और InvIT का विनियमन RBI करता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Both are trusts that let investors own units in finished, income-earning assets -- office parks and malls for REITs, toll roads, transmission lines and pipelines for InvITs -- and both must pass on at least 90 per cent of their net distributable cash flow. The government uses InvITs to monetise completed public assets. Statement 3 is wrong: REITs and InvITs are regulated by SEBI under separate regulations of 2014, and their units are listed on the stock exchanges.','कथन 1 और 2 सही हैं। दोनों ऐसे ट्रस्ट हैं जो निवेशकों को तैयार, आय देने वाली परिसंपत्तियों में यूनिट रखने देते हैं, REIT के लिए ऑफ़िस पार्क और मॉल, InvIT के लिए टोल सड़कें, पारेषण लाइनें और पाइपलाइनें; और दोनों को अपने शुद्ध वितरण योग्य नक़दी प्रवाह का कम से कम 90 प्रतिशत आगे देना होता है। सरकार पूरी हो चुकी सार्वजनिक परिसंपत्तियों के मुद्रीकरण के लिए InvIT का उपयोग करती है। कथन 3 गलत है: REIT और InvIT का विनियमन SEBI 2014 के अलग-अलग विनियमों के तहत करता है, और इनकी यूनिटें स्टॉक एक्सचेंजों पर सूचीबद्ध होती हैं।','fm-reits-invits','original_pattern_matched','Securities and Exchange Board of India (Real Estate Investment Trusts) and (Infrastructure Investment Trusts) Regulations, 2014.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','medium','Consider the following statements about bonds:','बॉन्डों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["A fixed-rate bond''s coupon rate is set at the time of issue.", "A zero-coupon bond makes no periodic interest payments.", "Treasury bills are issued at a discount and redeemed at their face value."], "statements_hi": ["स्थिर-दर वाले बॉन्ड की कूपन दर जारी करते समय तय होती है।", "शून्य-कूपन बॉन्ड कोई आवधिक ब्याज भुगतान नहीं करता।", "ट्रेज़री बिल बट्टे (discount) पर जारी किए जाते हैं और अंकित मूल्य पर भुनाए जाते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. The coupon stays fixed for the bond''s life, so it is the market price that adjusts when interest rates change. A zero-coupon bond, like a Treasury bill, is sold below face value, and the investor''s return is the difference between the price paid and the face value received at maturity.','तीनों कथन सही हैं। कूपन बॉन्ड के पूरे जीवनकाल में स्थिर रहता है, इसलिए ब्याज दरें बदलने पर बाज़ार मूल्य ही समायोजित होता है। ट्रेज़री बिल की तरह शून्य-कूपन बॉन्ड भी अंकित मूल्य से कम पर बेचा जाता है, और निवेशक का प्रतिफल चुकाए गए मूल्य और परिपक्वता पर मिलने वाले अंकित मूल्य का अंतर होता है।','fm-bond-coupon-zero-tbills','original_pattern_matched','Reserve Bank of India -- FAQs on Government Securities Market.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','medium','Consider the following statements about government securities in India:','भारत में सरकारी प्रतिभूतियों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["State Development Loans are securities issued by State Governments.", "The RBI Retail Direct platform lets individuals buy the bonds of private companies.", "Government securities carry a high risk of default."], "statements_hi": ["राज्य विकास ऋण (SDL) राज्य सरकारों द्वारा जारी की जाने वाली प्रतिभूतियाँ हैं।", "RBI रिटेल डायरेक्ट प्लेटफ़ॉर्म व्यक्तियों को निजी कंपनियों के बॉन्ड ख़रीदने देता है।", "सरकारी प्रतिभूतियों में चूक (default) का जोखिम अधिक होता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: the RBI auctions SDLs on behalf of the States, usually every week. Statement 2 is wrong: RBI Retail Direct, launched in 2021, lets individuals open a gilt account with the RBI to buy and sell government securities -- Treasury bills, dated securities, SDLs and sovereign gold bonds -- not corporate bonds. Statement 3 is wrong: government securities are regarded as practically free of default risk, which is why they are called gilt-edged; their prices still move with interest rates.','केवल कथन 1 सही है: RBI राज्यों की ओर से SDL की नीलामी करता है, सामान्यतः हर सप्ताह। कथन 2 गलत है: 2021 में शुरू किया गया RBI रिटेल डायरेक्ट व्यक्तियों को RBI के पास गिल्ट खाता खोलकर सरकारी प्रतिभूतियाँ, यानी ट्रेज़री बिल, दिनांकित प्रतिभूतियाँ, SDL और सॉवरेन गोल्ड बॉन्ड, ख़रीदने-बेचने देता है, कॉरपोरेट बॉन्ड नहीं। कथन 3 गलत है: सरकारी प्रतिभूतियों को चूक के जोखिम से लगभग मुक्त माना जाता है, इसीलिए इन्हें ''गिल्ट-एज्ड'' कहते हैं; फिर भी इनकी क़ीमतें ब्याज दरों के साथ बदलती हैं।','fm-gsecs-sdl-retail-direct','original_pattern_matched','Reserve Bank of India -- Retail Direct Scheme; FAQs on Government Securities Market.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','medium','Consider the following statements about money market instruments:','मुद्रा बाज़ार के उपकरणों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Commercial paper is an unsecured short-term instrument issued by companies.", "Certificates of deposit are issued by banks.", "In the call money market, funds are lent for periods of more than one year."], "statements_hi": ["वाणिज्यिक पत्र (commercial paper) कंपनियों द्वारा जारी किया जाने वाला बिना ज़मानत का अल्पकालिक उपकरण है।", "जमा प्रमाणपत्र (certificate of deposit) बैंकों द्वारा जारी किए जाते हैं।", "कॉल मनी बाज़ार में धन एक वर्ष से अधिक अवधि के लिए उधार दिया जाता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Commercial paper, issued at a discount for between 7 days and a year, lets highly rated companies borrow directly from investors; certificates of deposit are negotiable time deposits sold by banks, for up to a year. Statement 3 is wrong: call money is lent overnight -- notice money for 2 to 14 days, and term money for longer; together they meet banks'' very short-term needs.','कथन 1 और 2 सही हैं। 7 दिन से एक वर्ष तक के लिए बट्टे पर जारी वाणिज्यिक पत्र ऊँची रेटिंग वाली कंपनियों को सीधे निवेशकों से उधार लेने देता है; जमा प्रमाणपत्र बैंकों द्वारा एक वर्ष तक के लिए बेची जाने वाली परक्राम्य सावधि जमाएँ हैं। कथन 3 गलत है: कॉल मनी रातभर के लिए उधार दी जाती है; नोटिस मनी 2 से 14 दिन के लिए और टर्म मनी उससे अधिक के लिए होती है; ये मिलकर बैंकों की बहुत अल्पकालिक आवश्यकताएँ पूरी करती हैं।','fm-money-market-cp-cd-call','original_pattern_matched','Reserve Bank of India -- Master Directions on Money Market Instruments.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Masala bonds are rupee-denominated bonds issued outside India.", "In a masala bond, the currency risk is borne by the investor.", "India''s sovereign green bonds were first issued in 2023."], "statements_hi": ["मसाला बॉन्ड भारत के बाहर जारी किए जाने वाले रुपया-मूल्यवर्ग के बॉन्ड हैं।", "मसाला बॉन्ड में मुद्रा-जोखिम निवेशक उठाता है।", "भारत के सॉवरेन ग्रीन बॉन्ड पहली बार 2023 में जारी किए गए।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Masala bonds, first issued by the International Finance Corporation in 2014, let Indian borrowers raise money abroad in rupees, so a fall in the rupee hurts the foreign investor rather than the issuer. The Centre''s sovereign green bonds, first auctioned in January-February 2023, fund public projects that cut emissions, such as solar, wind and metro rail.','तीनों कथन सही हैं। 2014 में पहली बार अंतरराष्ट्रीय वित्त निगम द्वारा जारी मसाला बॉन्ड भारतीय उधारकर्ताओं को विदेश से रुपये में धन जुटाने देते हैं, इसलिए रुपये के गिरने से जारीकर्ता को नहीं, विदेशी निवेशक को हानि होती है। जनवरी-फ़रवरी 2023 में पहली बार नीलाम किए गए केंद्र के सॉवरेन ग्रीन बॉन्ड सौर, पवन और मेट्रो रेल जैसी उत्सर्जन घटाने वाली सार्वजनिक परियोजनाओं का वित्तपोषण करते हैं।','fm-masala-green-bonds','original_pattern_matched','Reserve Bank of India -- External Commercial Borrowings framework; Ministry of Finance -- Sovereign Green Bonds Framework.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','medium','Consider the following statements about insurance:','बीमा के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Insurance in India is regulated by the Insurance Regulatory and Development Authority of India.", "Reinsurance is extra cover that policyholders buy to top up their existing policies.", "Parametric insurance pays out only after a survey has assessed the actual loss suffered."], "statements_hi": ["भारत में बीमा का विनियमन भारतीय बीमा विनियामक और विकास प्राधिकरण (IRDAI) करता है।", "पुनर्बीमा (reinsurance) वह अतिरिक्त सुरक्षा है जो पॉलिसीधारक अपनी मौजूदा पॉलिसियों को बढ़ाने के लिए ख़रीदते हैं।", "पैरामीट्रिक बीमा केवल तभी भुगतान करता है जब किसी सर्वेक्षण से हुई वास्तविक हानि का आकलन हो जाए।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Statement 2 is wrong: reinsurance is insurance bought by insurance companies to pass on part of their own risk -- General Insurance Corporation of India (GIC Re) is the national reinsurer; a policyholder who wants more cover buys a top-up or a second policy. Statement 3 is wrong: parametric insurance pays a pre-agreed amount as soon as a measurable trigger is crossed -- rainfall below a level, wind speed above one -- without assessing each loss, which makes payouts fast; several States have tried it for heat waves and floods.','केवल कथन 1 सही है। कथन 2 गलत है: पुनर्बीमा बीमा कंपनियों द्वारा अपने जोखिम का एक भाग आगे देने के लिए ख़रीदा जाने वाला बीमा है; भारतीय साधारण बीमा निगम (GIC Re) राष्ट्रीय पुनर्बीमाकर्ता है; अधिक सुरक्षा चाहने वाला पॉलिसीधारक टॉप-अप या दूसरी पॉलिसी ख़रीदता है। कथन 3 गलत है: पैरामीट्रिक बीमा किसी मापने योग्य सीमा, जैसे एक स्तर से कम वर्षा या एक स्तर से अधिक पवन-गति, के पार होते ही पहले से तय राशि देता है, हर हानि का आकलन किए बिना, जिससे भुगतान जल्दी होता है; कई राज्यों ने इसे लू और बाढ़ के लिए आज़माया है।','fm-insurance-irdai-reinsurance-parametric','original_pattern_matched','Insurance Regulatory and Development Authority of India.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','medium','Consider the following statements about pension schemes:','पेंशन योजनाओं के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The National Pension System is regulated by the Pension Fund Regulatory and Development Authority.", "The Unified Pension Scheme assures 50 per cent of the average basic pay of the last 12 months for employees with 25 years of service.", "The Atal Pension Yojana is meant mainly for government employees."], "statements_hi": ["राष्ट्रीय पेंशन प्रणाली (NPS) का विनियमन पेंशन निधि विनियामक और विकास प्राधिकरण (PFRDA) करता है।", "एकीकृत पेंशन योजना (UPS) 25 वर्ष की सेवा वाले कर्मचारियों को अंतिम 12 महीनों के औसत मूल वेतन का 50 प्रतिशत सुनिश्चित करती है।", "अटल पेंशन योजना मुख्य रूप से सरकारी कर्मचारियों के लिए है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. The NPS, a defined-contribution scheme, has covered new Central Government recruits since 2004 and is open to all citizens; the UPS, effective from April 2025, is an option within the NPS for Central Government employees that restores an assured payout. Statement 3 is wrong: the Atal Pension Yojana (2015) is aimed at workers in the unorganised sector aged 18-40, offering a guaranteed monthly pension of 1,000 to 5,000 rupees from age 60.','कथन 1 और 2 सही हैं। परिभाषित-अंशदान वाली योजना NPS 2004 से केंद्र सरकार की नई भर्तियों पर लागू है और सभी नागरिकों के लिए खुली है; अप्रैल 2025 से प्रभावी UPS केंद्र सरकार के कर्मचारियों के लिए NPS के भीतर एक विकल्प है, जो सुनिश्चित भुगतान वापस लाता है। कथन 3 गलत है: अटल पेंशन योजना (2015) 18-40 वर्ष के असंगठित क्षेत्र के कामगारों के लिए है, जो 60 वर्ष की आयु से 1,000 से 5,000 रुपये की गारंटीशुदा मासिक पेंशन देती है।','fm-nps-ups-apy','original_pattern_matched','Pension Fund Regulatory and Development Authority; Ministry of Finance -- Unified Pension Scheme notification (2025).','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','medium','Consider the following statements about the Unified Payments Interface (UPI):','एकीकृत भुगतान इंटरफ़ेस (UPI) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It is run by NPCI, a not-for-profit company set up at the initiative of the RBI and the Indian Banks'' Association.", "It works only for transfers between accounts held in the same bank.", "It can be used only for payments of up to 10,000 rupees per transaction."], "statements_hi": ["इसे NPCI चलाता है, जो RBI और भारतीय बैंक संघ की पहल पर बनी एक गैर-लाभकारी कंपनी है।", "यह केवल एक ही बैंक के खातों के बीच अंतरण के लिए काम करता है।", "इसका उपयोग प्रति लेन-देन केवल 10,000 रुपये तक के भुगतान के लिए किया जा सकता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: NPCI, a Section 8 company under the Payment and Settlement Systems Act, 2007, also runs RuPay, IMPS, NACH and FASTag''s national electronic toll collection. Statement 2 is wrong: UPI''s value lies in interoperability -- any bank account can pay any other through any member app, and the transfers are settled between banks by NPCI. Statement 3 is wrong: the general limit is 1 lakh rupees per transaction, with higher limits for categories such as tax payments, hospitals, education and capital markets.','केवल कथन 1 सही है: भुगतान और निपटान प्रणाली अधिनियम, 2007 के तहत धारा 8 कंपनी NPCI रुपे, IMPS, NACH और फ़ास्टैग का राष्ट्रीय इलेक्ट्रॉनिक टोल संग्रह भी चलाती है। कथन 2 गलत है: UPI का मूल्य अंतर-संचालनीयता (interoperability) में है; कोई भी बैंक खाता किसी भी सदस्य ऐप के ज़रिए किसी भी दूसरे खाते को भुगतान कर सकता है, और अंतरणों का निपटान NPCI बैंकों के बीच करती है। कथन 3 गलत है: सामान्य सीमा प्रति लेन-देन 1 लाख रुपये है, और कर भुगतान, अस्पताल, शिक्षा तथा पूँजी बाज़ार जैसी श्रेणियों के लिए ऊँची सीमाएँ हैं।','fm-upi-npci-interoperability','original_pattern_matched','National Payments Corporation of India -- UPI product overview and circulars.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','medium','Consider the following statements about RTGS and NEFT:','RTGS और NEFT के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["RTGS has a minimum transaction amount of 5 lakh rupees.", "NEFT settles each transaction instantly, one at a time.", "RTGS is available only on bank working days."], "statements_hi": ["RTGS में न्यूनतम लेन-देन राशि 5 लाख रुपये है।", "NEFT हर लेन-देन का अलग-अलग, तुरंत निपटान करता है।", "RTGS केवल बैंक के कार्यदिवसों पर उपलब्ध है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb,2,0.66,'None of the statements is correct. RTGS, meant for large payments, has a minimum of 2 lakh rupees and settles each transaction individually in real time; NEFT has no minimum and settles in half-hourly batches. Both are run by the RBI and have been available round the clock on all days -- NEFT since December 2019 and RTGS since December 2020.','कोई भी कथन सही नहीं है। बड़े भुगतानों के लिए बने RTGS में न्यूनतम राशि 2 लाख रुपये है और यह हर लेन-देन का अलग-अलग, वास्तविक समय में निपटान करता है; NEFT में कोई न्यूनतम राशि नहीं है और इसका निपटान आधे-आधे घंटे के बैचों में होता है। दोनों RBI चलाता है और ये सभी दिनों में चौबीसों घंटे उपलब्ध हैं, NEFT दिसंबर 2019 से और RTGS दिसंबर 2020 से।','fm-rtgs-neft','original_pattern_matched','Reserve Bank of India -- FAQs on RTGS and NEFT.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','medium','Consider the following statements about the e-rupee (the RBI''s digital currency):','ई-रुपी, यानी RBI की डिजिटल मुद्रा, के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It is legal tender.", "The RBI began pilots of the e-rupee in 2022.", "Transactions in the e-rupee can be made only at bank branches."], "statements_hi": ["यह वैध मुद्रा (legal tender) है।", "RBI ने 2022 में ई-रुपी के पायलट शुरू किए।", "ई-रुपी में लेन-देन केवल बैंक शाखाओं पर ही किए जा सकते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. The e-rupee is a digital form of currency notes, issued by the RBI, with a wholesale pilot from November 2022 and a retail pilot from December 2022. Statement 3 is wrong: users hold the retail e-rupee in digital wallets offered by participating banks on their phones and pay person-to-person or at shops, including by scanning UPI QR codes; offline payments are also being tested.','कथन 1 और 2 सही हैं। ई-रुपी RBI द्वारा जारी करेंसी नोटों का डिजिटल रूप है; इसका थोक पायलट नवंबर 2022 से और खुदरा पायलट दिसंबर 2022 से चला। कथन 3 गलत है: उपयोगकर्ता खुदरा ई-रुपी को भाग लेने वाले बैंकों के डिजिटल वॉलेट में अपने फ़ोन पर रखते हैं और व्यक्ति-से-व्यक्ति या दुकानों पर, UPI QR कोड स्कैन करके भी, भुगतान करते हैं; ऑफ़लाइन भुगतान का भी परीक्षण हो रहा है।','fm-erupee-pilots','original_pattern_matched','Reserve Bank of India -- Concept Note on Central Bank Digital Currency (2022).','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','medium','Consider the following statements about account aggregators:','अकाउंट एग्रीगेटर के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Account aggregators are regulated by SEBI.", "They can share a user''s financial data with a lender only with the user''s consent.", "They can store users'' financial data and sell it to credit bureaus."], "statements_hi": ["अकाउंट एग्रीगेटर का विनियमन SEBI करता है।", "वे किसी उपयोगकर्ता का वित्तीय डेटा ऋणदाता से केवल उपयोगकर्ता की सहमति से ही साझा कर सकते हैं।", "वे उपयोगकर्ताओं का वित्तीय डेटा संग्रहित करके उसे क्रेडिट ब्यूरो को बेच सकते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 2 is correct: the user approves every request through a digital consent artefact that says what data is shared, with whom and for how long. Statement 1 is wrong: account aggregators are a class of NBFC licensed and regulated by the RBI, although the framework links banks, insurers, securities and pension regulators'' entities. Statement 3 is wrong: they are ''data-blind'' pipes -- they pass encrypted data from the holder to the user-approved recipient and may not store, read or sell it.','केवल कथन 2 सही है: उपयोगकर्ता हर अनुरोध को एक डिजिटल सहमति-पत्र (consent artefact) के ज़रिए स्वीकृत करता है, जो बताता है कि कौन-सा डेटा, किसके साथ और कितने समय के लिए साझा होगा। कथन 1 गलत है: अकाउंट एग्रीगेटर RBI द्वारा लाइसेंस प्राप्त और विनियमित NBFC की एक श्रेणी हैं, यद्यपि यह ढाँचा बैंकों, बीमा, प्रतिभूति और पेंशन विनियामकों की संस्थाओं को जोड़ता है। कथन 3 गलत है: ये ''डेटा-अंध'' (data-blind) माध्यम हैं; ये डेटा रखने वाले से उपयोगकर्ता द्वारा स्वीकृत प्राप्तकर्ता तक एन्क्रिप्टेड डेटा पहुँचाते हैं और उसे संग्रहित, पढ़ या बेच नहीं सकते।','fm-account-aggregators','original_pattern_matched','Reserve Bank of India -- Master Direction on NBFC-Account Aggregators (2016).','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','medium','Consider the following statements about some digital platforms for commerce and credit:','वाणिज्य और ऋण के कुछ डिजिटल प्लेटफ़ॉर्मों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Open Network for Digital Commerce (ONDC) is an open network protocol, not an e-commerce marketplace of its own.", "The Trade Receivables Discounting System (TReDS) helps MSMEs get their invoices on large buyers financed.", "Peer-to-peer lending platforms are regulated by SEBI."], "statements_hi": ["डिजिटल वाणिज्य के लिए खुला नेटवर्क (ONDC) एक खुला नेटवर्क प्रोटोकॉल है, अपने आप में कोई ई-कॉमर्स बाज़ार नहीं।", "व्यापार प्राप्य बट्टा प्रणाली (TReDS) MSME को बड़े ख़रीदारों पर उनके बिलों (invoices) का वित्तपोषण दिलाने में मदद करती है।", "पीयर-टू-पीयर (P2P) ऋण प्लेटफ़ॉर्मों का विनियमन SEBI करता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. ONDC, a Section 8 company promoted by the Department for Promotion of Industry and Internal Trade, lets any buyer app transact with any seller app, much as UPI did for payments; on TReDS platforms, such as RXIL, M1xchange and Invoicemart, financiers bid to discount MSMEs'' invoices on large buyers, cutting the wait for payment. Statement 3 is wrong: P2P lending platforms are registered as NBFC-P2P and regulated by the RBI, with caps on how much a lender may lend and a borrower may borrow.','कथन 1 और 2 सही हैं। उद्योग संवर्धन और आंतरिक व्यापार विभाग द्वारा प्रवर्तित धारा 8 कंपनी ONDC किसी भी ख़रीदार ऐप को किसी भी विक्रेता ऐप से लेन-देन करने देती है, जैसा UPI ने भुगतानों के लिए किया; RXIL, M1xchange और इनवॉइसमार्ट जैसे TReDS प्लेटफ़ॉर्मों पर वित्तदाता बड़े ख़रीदारों पर MSME के बिलों को भुनाने के लिए बोली लगाते हैं, जिससे भुगतान की प्रतीक्षा घटती है। कथन 3 गलत है: P2P ऋण प्लेटफ़ॉर्म NBFC-P2P के रूप में पंजीकृत होते हैं और RBI द्वारा विनियमित होते हैं, जिसमें इस पर सीमाएँ हैं कि कोई ऋणदाता कितना उधार दे और कोई उधारकर्ता कितना ले सकता है।','fm-ondc-treds-p2p','original_pattern_matched','Department for Promotion of Industry and Internal Trade -- ONDC; Reserve Bank of India -- TReDS and NBFC-P2P Directions.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','medium','Consider the following statements about the taxation of virtual digital assets (VDAs) in India:','भारत में आभासी डिजिटल परिसंपत्तियों (VDA) पर कराधान के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Gains from the transfer of VDAs are taxed at a flat rate of 30 per cent.", "Tax is deducted at source at 1 per cent on the transfer of VDAs above a threshold.", "Losses from VDAs can be set off against salary income.", "The RBI recognises Bitcoin as legal tender."], "statements_hi": ["VDA के हस्तांतरण से होने वाले लाभ पर 30 प्रतिशत की एकसमान दर से कर लगता है।", "एक सीमा से अधिक VDA के हस्तांतरण पर 1 प्रतिशत की दर से स्रोत पर कर कटौती (TDS) होती है।", "VDA से हुई हानि को वेतन से होने वाली आय के सामने समायोजित किया जा सकता है।", "RBI बिटकॉइन को वैध मुद्रा के रूप में मान्यता देता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": false}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. The Finance Act, 2022 taxed VDA gains at 30 per cent with no deduction except the cost of acquisition, and the TDS lets the tax department track trades. Statement 3 is wrong: VDA losses cannot be set off against any other income, nor carried forward. Statement 4 is wrong: taxing an asset does not make it legal money -- only the rupee, including the RBI''s e-rupee, is legal tender in India.','कथन 1 और 2 सही हैं। वित्त अधिनियम, 2022 ने VDA लाभ पर 30 प्रतिशत कर लगाया, जिसमें अधिग्रहण की लागत के अलावा कोई कटौती नहीं है, और TDS आयकर विभाग को सौदों पर नज़र रखने देता है। कथन 3 गलत है: VDA की हानि को किसी अन्य आय के सामने समायोजित नहीं किया जा सकता, न ही आगे ले जाया जा सकता है। कथन 4 गलत है: किसी परिसंपत्ति पर कर लगने से वह वैध मुद्रा नहीं बन जाती; भारत में केवल रुपया, जिसमें RBI का ई-रुपी भी शामिल है, वैध मुद्रा है।','fm-vda-taxation','original_pattern_matched','Income-tax Act, 1961, sections 115BBH and 194S (Finance Act, 2022).','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','medium','Consider the following statements about equity derivatives:','इक्विटी डेरिवेटिव के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["A futures contract creates an obligation for both the buyer and the seller.", "The buyer of an option has a right, but not an obligation, to buy or sell.", "The maximum loss of the buyer of an option is the premium paid.", "A SEBI study found that most individual traders in equity futures and options made profits."], "statements_hi": ["वायदा (futures) अनुबंध ख़रीदार और विक्रेता, दोनों के लिए दायित्व पैदा करता है।", "विकल्प (option) के ख़रीदार के पास ख़रीदने या बेचने का अधिकार होता है, दायित्व नहीं।", "विकल्प के ख़रीदार की अधिकतम हानि चुकाया गया प्रीमियम है।", "SEBI के एक अध्ययन में पाया गया कि इक्विटी वायदा और विकल्प के अधिकांश व्यक्तिगत व्यापारियों ने लाभ कमाया।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": true}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1, 2 and 3 are correct: the option seller, who collects the premium, carries the open-ended risk. Statement 4 is wrong: SEBI''s study of 2024 found that about 93 per cent of individual F&O traders lost money over three years, which led it to raise contract sizes and tighten rules on weekly expiries.','कथन 1, 2 और 3 सही हैं: प्रीमियम पाने वाला विकल्प-विक्रेता असीमित जोखिम उठाता है। कथन 4 गलत है: SEBI के 2024 के अध्ययन में पाया गया कि लगभग 93 प्रतिशत व्यक्तिगत F&O व्यापारियों को तीन वर्षों में हानि हुई, जिसके बाद उसने अनुबंधों का आकार बढ़ाया और साप्ताहिक समाप्ति (expiry) के नियम कड़े किए।','fm-derivatives-futures-options','original_pattern_matched','Securities and Exchange Board of India -- study on profit and loss of individual traders in equity F&O (2024).','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','medium','Consider the following statements about credit rating agencies:','क्रेडिट रेटिंग एजेंसियों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Credit rating agencies in India are regulated by SEBI.", "A higher credit rating usually lets a borrower raise money at a lower rate of interest.", "CRISIL was India''s first credit rating agency."], "statements_hi": ["भारत में क्रेडिट रेटिंग एजेंसियों का विनियमन SEBI करता है।", "ऊँची क्रेडिट रेटिंग प्रायः उधारकर्ता को कम ब्याज दर पर धन जुटाने देती है।", "CRISIL भारत की पहली क्रेडिट रेटिंग एजेंसी थी।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Ratings judge the likelihood that a borrower will repay on time; investors demand less compensation for lending to a safer borrower. CRISIL, set up in 1987, was followed by ICRA, CARE and others, all registered with SEBI under its 1999 regulations.','तीनों कथन सही हैं। रेटिंग यह आँकती है कि उधारकर्ता समय पर चुकाएगा या नहीं; सुरक्षित उधारकर्ता को उधार देने पर निवेशक कम प्रतिफल माँगते हैं। 1987 में बनी CRISIL के बाद ICRA, CARE और अन्य आईं, जो सभी SEBI के 1999 के विनियमों के तहत पंजीकृत हैं।','fm-credit-rating-agencies','original_pattern_matched','Securities and Exchange Board of India (Credit Rating Agencies) Regulations, 1999.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','medium','Consider the following statements about the stock market:','शेयर बाज़ार के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Sensex is made up of 50 stocks.", "The Nifty 50 is an index of the Bombay Stock Exchange.", "The Sensex and the Nifty 50 are compiled by SEBI."], "statements_hi": ["सेंसेक्स 50 शेयरों से बना है।", "निफ़्टी 50 बॉम्बे स्टॉक एक्सचेंज का सूचकांक है।", "सेंसेक्स और निफ़्टी 50 का संकलन SEBI करता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb,2,0.66,'None of the statements is correct. The Sensex of the BSE tracks 30 large companies, while the Nifty 50 of the National Stock Exchange tracks 50; both are weighted by free-float market capitalisation. The indices are compiled by the exchanges'' own index companies -- Asia Index for the BSE and NSE Indices for the NSE; SEBI regulates the exchanges but does not build their indices.','कोई भी कथन सही नहीं है। BSE का सेंसेक्स 30 बड़ी कंपनियों को, जबकि नेशनल स्टॉक एक्सचेंज का निफ़्टी 50, 50 कंपनियों को मापता है; दोनों मुक्त-प्रवाह (free-float) बाज़ार पूँजीकरण से भारित हैं। ये सूचकांक एक्सचेंजों की अपनी सूचकांक कंपनियाँ बनाती हैं, BSE के लिए एशिया इंडेक्स और NSE के लिए NSE इंडाइसेज़; SEBI एक्सचेंजों का विनियमन करता है, पर उनके सूचकांक नहीं बनाता।','fm-sensex-nifty-compilers','original_pattern_matched','BSE Limited; National Stock Exchange of India -- index methodology.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','medium','Consider the following statements about mutual funds:','म्यूचुअल फ़ंडों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Mutual funds in India are regulated by SEBI.", "An index fund picks stocks in an attempt to beat its benchmark index.", "Units of an open-ended scheme can be bought and redeemed on any business day."], "statements_hi": ["भारत में म्यूचुअल फ़ंडों का विनियमन SEBI करता है।", "इंडेक्स फ़ंड अपने बेंचमार्क सूचकांक से आगे निकलने के प्रयास में शेयर चुनता है।", "खुले-अंत (open-ended) वाली योजना की यूनिटें किसी भी कार्यदिवस पर ख़रीदी और भुनाई जा सकती हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 3 are correct: open-ended schemes buy and redeem units daily at the net asset value, while closed-ended schemes have a fixed term and are traded on exchanges. Statement 2 is wrong: an index fund is passive -- it simply holds the shares of an index in the same proportions to match its return at low cost; it is actively managed funds that try to beat the benchmark.','कथन 1 और 3 सही हैं: खुले-अंत वाली योजनाएँ हर दिन शुद्ध परिसंपत्ति मूल्य (NAV) पर यूनिटें ख़रीदती और भुनाती हैं, जबकि बंद-अंत वाली योजनाओं की अवधि निश्चित होती है और उनका व्यापार एक्सचेंजों पर होता है। कथन 2 गलत है: इंडेक्स फ़ंड निष्क्रिय (passive) होता है; वह किसी सूचकांक के शेयरों को उन्हीं अनुपातों में रखता है, ताकि कम लागत पर उसके बराबर प्रतिफल दे; बेंचमार्क से आगे निकलने का प्रयास सक्रिय रूप से प्रबंधित फ़ंड करते हैं।','fm-mutual-funds-index-open-ended','original_pattern_matched','Securities and Exchange Board of India (Mutual Funds) Regulations, 1996.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','medium','Consider the following statements about International Financial Services Centres (IFSCs):','अंतरराष्ट्रीय वित्तीय सेवा केंद्रों (IFSC) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The International Financial Services Centres Authority is a unified regulator for IFSCs.", "India''s first IFSC is at GIFT City in Gujarat.", "Transactions in an IFSC are carried out mostly in foreign currency."], "statements_hi": ["अंतरराष्ट्रीय वित्तीय सेवा केंद्र प्राधिकरण (IFSCA) IFSC के लिए एकीकृत विनियामक है।", "भारत का पहला IFSC गुजरात की GIFT सिटी में है।", "IFSC में लेन-देन अधिकतर विदेशी मुद्रा में होते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Set up in 2020, the IFSCA combines within the IFSC the powers of the RBI, SEBI, IRDAI and PFRDA; GIFT IFSC hosts international exchanges, bank branches, aircraft-leasing firms and fund managers, and is meant to bring back to India financial business that went to Singapore, Dubai and London.','तीनों कथन सही हैं। 2020 में बना IFSCA, IFSC के भीतर RBI, SEBI, IRDAI और PFRDA की शक्तियों को मिलाता है; GIFT IFSC में अंतरराष्ट्रीय एक्सचेंज, बैंक शाखाएँ, विमान पट्टे (leasing) वाली कंपनियाँ और फ़ंड प्रबंधक हैं, और इसका उद्देश्य उस वित्तीय कारोबार को भारत वापस लाना है जो सिंगापुर, दुबई और लंदन चला गया था।','fm-ifsca-gift-city','original_pattern_matched','International Financial Services Centres Authority Act, 2019.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','medium','Consider the following statements about trading in shares:','शेयरों में व्यापार के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Circuit breakers halt trading when a market index moves too sharply in a day.", "Short selling means selling shares one does not own, hoping to buy them back later at a lower price.", "A bear market is one in which share prices are rising."], "statements_hi": ["जब कोई बाज़ार सूचकांक एक दिन में बहुत तेज़ी से बदलता है, तो सर्किट ब्रेकर व्यापार रोक देते हैं।", "शॉर्ट सेलिंग का अर्थ है ऐसे शेयर बेचना जो अपने पास नहीं हैं, इस उम्मीद में कि बाद में उन्हें कम मूल्य पर वापस ख़रीद लेंगे।", "मंदड़िया (bear) बाज़ार वह है जिसमें शेयरों की क़ीमतें बढ़ रही होती हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Index-wide circuit breakers at 10, 15 and 20 per cent pause trading to let panic cool. Short sellers profit when prices fall, and in India they must be able to deliver the shares at settlement. Statement 3 is wrong: in a bear market prices are falling and pessimism prevails; a market in which prices are rising is a bull market.','कथन 1 और 2 सही हैं। पूरे सूचकांक पर 10, 15 और 20 प्रतिशत के सर्किट ब्रेकर घबराहट को शांत होने देने के लिए व्यापार रोकते हैं। कीमतें गिरने पर शॉर्ट सेलर लाभ कमाते हैं, और भारत में उन्हें निपटान के समय शेयर देने में सक्षम होना चाहिए। कथन 3 गलत है: मंदड़िया बाज़ार में कीमतें गिर रही होती हैं और निराशा हावी रहती है; जिस बाज़ार में कीमतें बढ़ रही हों, वह तेज़ड़िया (bull) बाज़ार है।','fm-circuit-breakers-short-selling-bear','original_pattern_matched','Securities and Exchange Board of India -- index-based market-wide circuit breakers; framework for short selling.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Shares represent part ownership of a company.", "Bondholders are the owners of the company that issued the bonds."], "statements_hi": ["शेयर किसी कंपनी के आंशिक स्वामित्व को दर्शाते हैं।", "बॉन्डधारक बॉन्ड जारी करने वाली कंपनी के स्वामी होते हैं।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Statement 2 is wrong: bondholders are lenders -- they are paid interest and principal before shareholders get anything, which is why bonds are generally less risky than shares.','केवल कथन 1 सही है। कथन 2 गलत है: बॉन्डधारक ऋणदाता होते हैं; शेयरधारकों को कुछ भी मिलने से पहले उन्हें ब्याज और मूलधन मिलता है, इसीलिए बॉन्ड सामान्यतः शेयरों से कम जोखिम वाले होते हैं।','fm-shares-bonds-easy','original_pattern_matched','NCERT Class XII, Business Studies -- Financial Markets.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Stock exchanges in India are regulated by the Ministry of Commerce.", "Companies can raise money by issuing shares."], "statements_hi": ["भारत में स्टॉक एक्सचेंजों का विनियमन वाणिज्य मंत्रालय करता है।", "कंपनियाँ शेयर जारी करके धन जुटा सकती हैं।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 2 is correct. Statement 1 is wrong: stock exchanges are regulated by SEBI, which falls under the Ministry of Finance.','केवल कथन 2 सही है। कथन 1 गलत है: स्टॉक एक्सचेंजों का विनियमन SEBI करता है, जो वित्त मंत्रालय के अंतर्गत आता है।','fm-exchange-regulator-easy','original_pattern_matched','NCERT Class XII, Business Studies -- Financial Markets.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["UPI can be used to send money using a mobile phone.", "A debit card lets its holder spend money from his or her own bank account."], "statements_hi": ["UPI का उपयोग मोबाइल फ़ोन से पैसे भेजने के लिए किया जा सकता है।", "डेबिट कार्ड उसके धारक को अपने बैंक खाते से पैसा ख़र्च करने देता है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct. A debit card draws on money already in the account, whereas a credit card spends money lent by the card issuer, to be repaid later.','दोनों कथन सही हैं। डेबिट कार्ड खाते में पहले से मौजूद पैसे का उपयोग करता है, जबकि क्रेडिट कार्ड कार्ड जारीकर्ता द्वारा उधार दिया गया पैसा ख़र्च करता है, जिसे बाद में चुकाना होता है।','fm-upi-debit-card-easy','original_pattern_matched','Reserve Bank of India -- Financial Education.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The returns of mutual funds are guaranteed by SEBI.", "Mutual funds can invest only in government bonds."], "statements_hi": ["म्यूचुअल फ़ंडों के प्रतिफल की गारंटी SEBI देता है।", "म्यूचुअल फ़ंड केवल सरकारी बॉन्डों में ही निवेश कर सकते हैं।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": true}]'::jsonb,2,0.66,'Neither statement is correct. Mutual fund investments are subject to market risk and returns are not guaranteed by anyone; SEBI regulates the funds but does not insure them. Funds invest in shares, corporate and government bonds, money market instruments and gold, according to each scheme''s objective.','कोई भी कथन सही नहीं है। म्यूचुअल फ़ंड निवेश बाज़ार जोखिम के अधीन हैं और उनके प्रतिफल की गारंटी कोई नहीं देता; SEBI फ़ंडों का विनियमन करता है, पर उनका बीमा नहीं करता। फ़ंड हर योजना के उद्देश्य के अनुसार शेयरों, कॉरपोरेट और सरकारी बॉन्डों, मुद्रा बाज़ार उपकरणों और सोने में निवेश करते हैं।','fm-mutual-fund-risk-easy','original_pattern_matched','Securities and Exchange Board of India -- Investor education.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Insurance protects against financial loss from uncertain events.", "The premium is the amount that the insurer pays the policyholder when a claim is made."], "statements_hi": ["बीमा अनिश्चित घटनाओं से होने वाली वित्तीय हानि से सुरक्षा देता है।", "प्रीमियम वह राशि है जो दावा करने पर बीमाकर्ता पॉलिसीधारक को देता है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Statement 2 is wrong: the premium is what the policyholder pays the insurer for cover; what the insurer pays on a valid claim is the claim amount or sum assured.','केवल कथन 1 सही है। कथन 2 गलत है: प्रीमियम वह राशि है जो पॉलिसीधारक सुरक्षा के लिए बीमाकर्ता को देता है; वैध दावे पर बीमाकर्ता जो देता है, वह दावा राशि या बीमित राशि है।','fm-insurance-premium-easy','original_pattern_matched','Insurance Regulatory and Development Authority of India -- Policyholder education.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The National Stock Exchange was set up before the Bombay Stock Exchange.", "The Bombay Stock Exchange is the oldest stock exchange in Asia."], "statements_hi": ["नेशनल स्टॉक एक्सचेंज की स्थापना बॉम्बे स्टॉक एक्सचेंज से पहले हुई।", "बॉम्बे स्टॉक एक्सचेंज एशिया का सबसे पुराना स्टॉक एक्सचेंज है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 2 is correct: the BSE traces its origin to share brokers who met under a banyan tree in Bombay in 1875. Statement 1 is wrong: the NSE was set up only in 1992 and began trading in 1994, introducing screen-based trading across the country.','केवल कथन 2 सही है: BSE की शुरुआत 1875 में बॉम्बे में एक बरगद के पेड़ के नीचे मिलने वाले शेयर दलालों से मानी जाती है। कथन 1 गलत है: NSE की स्थापना 1992 में हुई और इसमें व्यापार 1994 में शुरू हुआ, जिसने पूरे देश में स्क्रीन-आधारित व्यापार शुरू किया।','fm-bse-nse-easy','original_pattern_matched','BSE Limited; National Stock Exchange of India.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["A fixed deposit is a kind of time deposit.", "Banks usually pay a higher interest rate on savings accounts than on fixed deposits."], "statements_hi": ["सावधि जमा (fixed deposit) एक प्रकार की मीयादी जमा (time deposit) है।", "बैंक प्रायः सावधि जमाओं की तुलना में बचत खातों पर अधिक ब्याज दर देते हैं।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Statement 2 is wrong: because a fixed deposit locks money in for a set period, banks can use it with more certainty and pay a higher rate on it than on a savings account, from which money can be withdrawn at any time.','केवल कथन 1 सही है। कथन 2 गलत है: चूँकि सावधि जमा धन को एक निश्चित अवधि के लिए बाँध देती है, बैंक उसका अधिक निश्चितता से उपयोग कर सकते हैं और उस पर बचत खाते से अधिक दर देते हैं, जिससे पैसा कभी भी निकाला जा सकता है।','fm-fixed-deposit-easy','original_pattern_matched','Reserve Bank of India -- Financial Education.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["A cheque is a negotiable instrument.", "A demat account holds shares in electronic form."], "statements_hi": ["चेक एक परक्राम्य लिखत (negotiable instrument) है।", "डीमैट खाता शेयरों को इलेक्ट्रॉनिक रूप में रखता है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct. Cheques, promissory notes and bills of exchange are governed by the Negotiable Instruments Act, 1881; demat accounts are held with depository participants of the two depositories, NSDL and CDSL.','दोनों कथन सही हैं। चेक, वचन-पत्र और विनिमय-पत्र परक्राम्य लिखत अधिनियम, 1881 से नियंत्रित होते हैं; डीमैट खाते दो डिपॉज़िटरी, NSDL और CDSL, के डिपॉज़िटरी प्रतिभागियों के पास होते हैं।','fm-cheque-demat-easy','original_pattern_matched','Negotiable Instruments Act, 1881; Depositories Act, 1996.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','hard','Consider the following statements about Additional Tier-1 (AT1) bonds issued by banks:','बैंकों द्वारा जारी अतिरिक्त टियर-1 (AT1) बॉन्डों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["They can be written down if a bank''s capital falls below a trigger level.", "They have a fixed maturity of ten years.", "They count towards a bank''s regulatory capital."], "statements_hi": ["यदि किसी बैंक की पूँजी एक निर्धारित स्तर से नीचे गिर जाए, तो इन्हें बट्टे खाते में डाला (write down) जा सकता है।", "इनकी दस वर्ष की निश्चित परिपक्वता होती है।", "ये बैंक की विनियामक पूँजी में गिने जाते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 3 are correct. AT1 bonds are loss-absorbing: when Yes Bank was rescued in 2020, its AT1 bonds of about 8,400 crore rupees were written off entirely. They pay higher interest because of this risk and count as Tier-1 capital under Basel III. Statement 2 is wrong: AT1 bonds are perpetual -- they have no maturity date, although the issuer may call them back after five years with the RBI''s approval.','कथन 1 और 3 सही हैं। AT1 बॉन्ड हानि सोखने वाले होते हैं: 2020 में यस बैंक को बचाते समय उसके लगभग 8,400 करोड़ रुपये के AT1 बॉन्ड पूरी तरह बट्टे खाते में डाल दिए गए। इसी जोखिम के कारण ये अधिक ब्याज देते हैं और बेसल III के तहत टियर-1 पूँजी में गिने जाते हैं। कथन 2 गलत है: AT1 बॉन्ड स्थायी (perpetual) होते हैं; इनकी कोई परिपक्वता तिथि नहीं होती, यद्यपि जारीकर्ता RBI की अनुमति से पाँच वर्ष बाद इन्हें वापस बुला (call) सकता है।','fm-at1-bonds','original_pattern_matched','Reserve Bank of India -- Master Circular on Basel III Capital Regulations.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','hard','Consider the following statements about the yield curve:','प्रतिफल वक्र (yield curve) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["An inverted yield curve means that short-term yields are higher than long-term yields.", "An inverted yield curve is usually a sign that markets expect strong economic growth.", "The yield curve plots bond yields against the credit ratings of the issuers."], "statements_hi": ["उलटे (inverted) प्रतिफल वक्र का अर्थ है कि अल्पकालिक प्रतिफल दीर्घकालिक प्रतिफल से अधिक हैं।", "उलटा प्रतिफल वक्र प्रायः इस बात का संकेत है कि बाज़ार तेज़ आर्थिक वृद्धि की आशा कर रहे हैं।", "प्रतिफल वक्र बॉन्ड प्रतिफलों को जारीकर्ताओं की क्रेडिट रेटिंग के सामने अंकित करता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Statement 2 is wrong: an inverted curve usually signals that markets expect interest rates to fall because growth will weaken -- in the United States it has preceded most recessions of the past half-century; a normal, upward-sloping curve goes with expectations of growth. Statement 3 is wrong: the yield curve plots yields against maturity for bonds of the same credit quality, typically government securities.','केवल कथन 1 सही है। कथन 2 गलत है: उलटा वक्र प्रायः यह संकेत देता है कि बाज़ार ब्याज दरें घटने की आशा कर रहे हैं, क्योंकि वृद्धि कमज़ोर होगी; संयुक्त राज्य अमेरिका में यह पिछली आधी सदी की अधिकांश मंदियों से पहले दिखा है; सामान्य, ऊपर की ओर उठता वक्र वृद्धि की आशा से जुड़ा होता है। कथन 3 गलत है: प्रतिफल वक्र एक ही क्रेडिट गुणवत्ता वाले बॉन्डों, सामान्यतः सरकारी प्रतिभूतियों, के प्रतिफलों को परिपक्वता के सामने अंकित करता है।','fm-yield-curve-inversion','original_pattern_matched','Reserve Bank of India -- Financial Stability Report; Clearing Corporation of India -- yield curves.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','hard','Consider the following statements about investment risk:','निवेश जोखिम के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["A share with a beta greater than 1 tends to rise and fall more than the market as a whole.", "Diversifying across many companies reduces unsystematic risk.", "Systematic risk affects the whole market and cannot be removed by diversification."], "statements_hi": ["1 से अधिक बीटा वाला शेयर पूरे बाज़ार की तुलना में अधिक चढ़ता-गिरता है।", "कई कंपनियों में विविधीकरण (diversification) अव्यवस्थित (unsystematic) जोखिम को घटाता है।", "व्यवस्थित (systematic) जोखिम पूरे बाज़ार को प्रभावित करता है और विविधीकरण से दूर नहीं किया जा सकता।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Beta measures how sensitive a share is to market movements. Company-specific shocks -- a strike, a product failure -- average out across a large portfolio, but economy-wide shocks such as a rate rise, a war or a recession hit nearly every share, so that risk can only be hedged, not diversified away.','तीनों कथन सही हैं। बीटा मापता है कि कोई शेयर बाज़ार की चाल के प्रति कितना संवेदनशील है। कंपनी-विशेष झटके, जैसे हड़ताल या किसी उत्पाद की विफलता, बड़े पोर्टफ़ोलियो में औसत हो जाते हैं, पर दर वृद्धि, युद्ध या मंदी जैसे पूरी अर्थव्यवस्था वाले झटके लगभग हर शेयर को प्रभावित करते हैं, इसलिए उस जोखिम का केवल बचाव (hedging) किया जा सकता है, विविधीकरण से उसे हटाया नहीं जा सकता।','fm-beta-systematic-risk','original_pattern_matched','Securities and Exchange Board of India -- Investor education.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','hard','Consider the following statements about the resolution of bad loans:','डूबे ऋणों के समाधान के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Asset reconstruction companies buy bad loans from banks.", "Asset reconstruction companies issue security receipts to raise funds for such purchases.", "Securitisation converts illiquid loans into securities that can be traded."], "statements_hi": ["परिसंपत्ति पुनर्निर्माण कंपनियाँ (ARC) बैंकों से डूबे ऋण ख़रीदती हैं।", "ARC ऐसी ख़रीद के लिए धन जुटाने हेतु प्रतिभूति रसीदें (security receipts) जारी करती हैं।", "प्रतिभूतिकरण (securitisation) अतरल ऋणों को ऐसी प्रतिभूतियों में बदलता है जिनका व्यापार हो सके।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Under the SARFAESI Act, 2002, ARCs registered with the RBI buy non-performing loans at a discount, paying partly in cash and partly in security receipts, and then try to recover the dues; the National Asset Reconstruction Company Ltd, set up in 2021, was meant to take over large stressed loans of banks.','तीनों कथन सही हैं। SARFAESI अधिनियम, 2002 के तहत RBI में पंजीकृत ARC अनर्जक ऋणों को बट्टे पर ख़रीदती हैं, कुछ भुगतान नक़द और कुछ प्रतिभूति रसीदों में करती हैं, और फिर बकाया वसूलने का प्रयास करती हैं; 2021 में बनी नेशनल एसेट रिकंस्ट्रक्शन कंपनी लिमिटेड का उद्देश्य बैंकों के बड़े दबावग्रस्त ऋणों को अपने हाथ में लेना था।','fm-arcs-securitisation','original_pattern_matched','Securitisation and Reconstruction of Financial Assets and Enforcement of Security Interest (SARFAESI) Act, 2002.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','hard','Consider the following statements about tokenisation:','टोकनीकरण (tokenisation) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Card tokenisation replaces the actual card details with a unique code for online payments.", "Tokenisation of real-world assets represents ownership of an asset, such as a building or a bond, as a digital token on a blockchain.", "A public blockchain is controlled by a single central authority."], "statements_hi": ["कार्ड टोकनीकरण ऑनलाइन भुगतानों के लिए वास्तविक कार्ड विवरण को एक अद्वितीय कोड से बदल देता है।", "वास्तविक परिसंपत्तियों का टोकनीकरण किसी इमारत या बॉन्ड जैसी परिसंपत्ति के स्वामित्व को ब्लॉकचेन पर एक डिजिटल टोकन के रूप में दर्शाता है।", "सार्वजनिक ब्लॉकचेन एक ही केंद्रीय प्राधिकरण द्वारा नियंत्रित होता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Since October 2022 merchants in India may not store card numbers; they hold a token that is useless if stolen. Tokenising real-world assets can split costly assets into small, easily traded units and settle trades quickly. Statement 3 is wrong: a public blockchain is decentralised -- anyone can join and verify transactions, and no single body controls the ledger; permissioned blockchains restrict who may take part.','कथन 1 और 2 सही हैं। अक्टूबर 2022 से भारत में व्यापारी कार्ड संख्याएँ संग्रहित नहीं कर सकते; वे एक टोकन रखते हैं, जो चोरी होने पर बेकार है। वास्तविक परिसंपत्तियों का टोकनीकरण महँगी परिसंपत्तियों को छोटी, आसानी से बिकने वाली इकाइयों में बाँट सकता है और सौदों का निपटान जल्दी कर सकता है। कथन 3 गलत है: सार्वजनिक ब्लॉकचेन विकेंद्रीकृत होता है; कोई भी उससे जुड़कर लेन-देन सत्यापित कर सकता है, और कोई एक निकाय बहीखाते को नियंत्रित नहीं करता; अनुमति-आधारित (permissioned) ब्लॉकचेन सीमित करते हैं कि कौन भाग ले सकता है।','fm-tokenisation-blockchain','original_pattern_matched','Reserve Bank of India -- Card-on-File Tokenisation (2021-22).','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','hard','Consider the following statements about some trading practices:','कुछ व्यापारिक प्रथाओं के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Margin trading lets an investor buy shares partly with money borrowed from the broker.", "In short selling, the maximum possible loss is limited to the amount received from the sale.", "Naked short selling is permitted in India."], "statements_hi": ["मार्जिन ट्रेडिंग निवेशक को आंशिक रूप से ब्रोकर से उधार लिए पैसे से शेयर ख़रीदने देती है।", "शॉर्ट सेलिंग में अधिकतम संभावित हानि बिक्री से प्राप्त राशि तक सीमित होती है।", "भारत में नेकेड शॉर्ट सेलिंग की अनुमति है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Statement 2 is wrong: a short seller must buy back the shares later, and since there is no ceiling on how high a price can rise, the possible loss is unlimited. Statement 3 is wrong: SEBI does not allow naked short selling -- every seller must be able to deliver the shares at settlement, borrowing them if necessary through the securities lending and borrowing mechanism.','केवल कथन 1 सही है। कथन 2 गलत है: शॉर्ट सेलर को बाद में शेयर वापस ख़रीदने होते हैं, और चूँकि मूल्य कितना भी ऊँचा जा सकता है, संभावित हानि असीमित है। कथन 3 गलत है: SEBI नेकेड शॉर्ट सेलिंग की अनुमति नहीं देता; हर विक्रेता को निपटान के समय शेयर देने में सक्षम होना चाहिए, ज़रूरत हो तो प्रतिभूति उधार देने और लेने की व्यवस्था से उन्हें उधार लेकर।','fm-margin-short-selling','original_pattern_matched','Securities and Exchange Board of India -- Framework for short selling; Margin Trading Facility.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','hard','Consider the following statements about insurance products and channels:','बीमा उत्पादों और माध्यमों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Bancassurance means banks selling the insurance products of insurers.", "Microinsurance products have low premiums and small sums assured.", "In a unit-linked insurance plan, the investment risk is borne by the insurer."], "statements_hi": ["बैंकएश्योरेंस का अर्थ है बैंकों द्वारा बीमा कंपनियों के उत्पाद बेचना।", "सूक्ष्म बीमा (microinsurance) उत्पादों में प्रीमियम कम और बीमित राशि छोटी होती है।", "यूनिट-लिंक्ड बीमा योजना (ULIP) में निवेश का जोखिम बीमा कंपनी उठाती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Banks'' wide branch networks make them a major channel for selling insurance, and microinsurance is designed for low-income households. Statement 3 is wrong: in a ULIP, part of the premium is invested in funds chosen by the policyholder, who bears the market risk -- the value of the policy rises and falls with the funds.','कथन 1 और 2 सही हैं। बैंकों का व्यापक शाखा नेटवर्क उन्हें बीमा बेचने का एक प्रमुख माध्यम बनाता है, और सूक्ष्म बीमा कम आय वाले परिवारों के लिए बनाया गया है। कथन 3 गलत है: ULIP में प्रीमियम का एक भाग पॉलिसीधारक द्वारा चुने गए फ़ंडों में लगाया जाता है, और बाज़ार जोखिम वही उठाता है; पॉलिसी का मूल्य फ़ंडों के साथ बढ़ता-घटता है।','fm-bancassurance-micro-ulip','original_pattern_matched','Insurance Regulatory and Development Authority of India.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','mcq','medium','Which one of the following allows a listed company to raise capital from qualified institutional buyers without making a full public issue?','निम्नलिखित में से कौन-सा किसी सूचीबद्ध कंपनी को पूर्ण सार्वजनिक निर्गम किए बिना योग्य संस्थागत ख़रीदारों से पूँजी जुटाने देता है?','{}'::jsonb,'[{"id": "a", "body": "Rights issue to existing shareholders", "body_hi": "मौजूदा शेयरधारकों के लिए राइट्स इश्यू", "isCorrect": false}, {"id": "b", "body": "Initial public offering", "body_hi": "प्रारंभिक सार्वजनिक निर्गम (IPO)", "isCorrect": false}, {"id": "c", "body": "Qualified institutional placement", "body_hi": "योग्य संस्थागत नियोजन (QIP)", "isCorrect": true}, {"id": "d", "body": "Bonus issue", "body_hi": "बोनस इश्यू", "isCorrect": false}]'::jsonb,2,0.66,'A QIP lets a listed company sell shares or convertible securities quickly to institutions such as mutual funds and insurers, with far fewer formalities than a public offer. A rights issue offers new shares to existing shareholders, and a bonus issue gives them free shares out of reserves without raising any money.','QIP किसी सूचीबद्ध कंपनी को म्यूचुअल फ़ंडों और बीमा कंपनियों जैसी संस्थाओं को सार्वजनिक निर्गम की तुलना में बहुत कम औपचारिकताओं के साथ जल्दी शेयर या परिवर्तनीय प्रतिभूतियाँ बेचने देता है। राइट्स इश्यू मौजूदा शेयरधारकों को नए शेयर देता है, और बोनस इश्यू बिना कोई धन जुटाए आरक्षित निधि से उन्हें मुफ़्त शेयर देता है।','fm-qip','original_pattern_matched','Securities and Exchange Board of India (Issue of Capital and Disclosure Requirements) Regulations, 2018.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','mcq','medium','SEBI''s SCORES platform is used for:','SEBI का SCORES प्लेटफ़ॉर्म किस काम आता है?','{}'::jsonb,'[{"id": "a", "body": "registering and tracking investors'' complaints", "body_hi": "निवेशकों की शिकायतें दर्ज करना और उन पर नज़र रखना", "isCorrect": true}, {"id": "b", "body": "rating the creditworthiness of companies that issue bonds", "body_hi": "बॉन्ड जारी करने वाली कंपनियों की ऋण-योग्यता की रेटिंग", "isCorrect": false}, {"id": "c", "body": "settling trades between stockbrokers", "body_hi": "स्टॉकब्रोकरों के बीच सौदों का निपटान", "isCorrect": false}, {"id": "d", "body": "approving new mutual fund schemes", "body_hi": "नई म्यूचुअल फ़ंड योजनाओं को स्वीकृति देना", "isCorrect": false}]'::jsonb,2,0.66,'SCORES (SEBI Complaints Redress System) is an online system on which investors lodge complaints against listed companies and intermediaries and follow their progress; unresolved disputes can go to the online dispute resolution platform. Trades are settled by clearing corporations, and ratings come from credit rating agencies.','SCORES (SEBI शिकायत निवारण प्रणाली) एक ऑनलाइन प्रणाली है, जिस पर निवेशक सूचीबद्ध कंपनियों और मध्यस्थों के विरुद्ध शिकायतें दर्ज करते हैं और उनकी प्रगति देखते हैं; अनसुलझे विवाद ऑनलाइन विवाद समाधान प्लेटफ़ॉर्म पर जा सकते हैं। सौदों का निपटान क्लियरिंग कॉरपोरेशन करते हैं, और रेटिंग क्रेडिट रेटिंग एजेंसियाँ देती हैं।','fm-scores-grievances','original_pattern_matched','Securities and Exchange Board of India -- SCORES.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','mcq','medium','The RBI''s ''regulatory sandbox'' framework allows:','RBI का ''विनियामक सैंडबॉक्स'' (regulatory sandbox) ढाँचा किसकी अनुमति देता है?','{}'::jsonb,'[{"id": "a", "body": "banks to stop maintaining the Cash Reserve Ratio for a year", "body_hi": "बैंकों को एक वर्ष तक नकद आरक्षित अनुपात न रखने", "isCorrect": false}, {"id": "b", "body": "foreign banks to open branches without a licence from the RBI", "body_hi": "विदेशी बैंकों को RBI के लाइसेंस के बिना शाखाएँ खोलने", "isCorrect": false}, {"id": "c", "body": "companies to issue shares to the public without filing an offer document for a year", "body_hi": "कंपनियों को एक वर्ष तक बिना प्रस्ताव दस्तावेज़ दाख़िल किए जनता को शेयर जारी करने", "isCorrect": false}, {"id": "d", "body": "fintech firms to test new products with real customers under relaxed rules", "body_hi": "फ़िनटेक कंपनियों को ढीले नियमों में वास्तविक ग्राहकों के साथ नए उत्पादों का परीक्षण", "isCorrect": true}]'::jsonb,2,0.66,'Under the sandbox, first run in 2019, selected firms test innovations -- in retail payments, cross-border payments, MSME lending or fraud prevention -- on a limited scale and for a limited time, with safeguards for customers; the regulator learns from the trial before writing permanent rules. SEBI, IRDAI and the IFSCA run similar sandboxes.','2019 में पहली बार चलाए गए सैंडबॉक्स के तहत चुनी हुई कंपनियाँ खुदरा भुगतान, सीमा-पार भुगतान, MSME ऋण या धोखाधड़ी रोकथाम जैसे नवाचारों का सीमित पैमाने पर और सीमित समय के लिए, ग्राहकों की सुरक्षा के साथ, परीक्षण करती हैं; स्थायी नियम बनाने से पहले विनियामक इस परीक्षण से सीखता है। SEBI, IRDAI और IFSCA भी ऐसे ही सैंडबॉक्स चलाते हैं।','fm-regulatory-sandbox','original_pattern_matched','Reserve Bank of India -- Enabling Framework for Regulatory Sandbox.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','mcq','medium','''e-RUPI'', launched in 2021, is:','2021 में शुरू किया गया ''ई-रूपी'' (e-RUPI) क्या है?','{}'::jsonb,'[{"id": "a", "body": "the retail form of the RBI''s central bank digital currency", "body_hi": "RBI की केंद्रीय बैंक डिजिटल मुद्रा का खुदरा रूप", "isCorrect": false}, {"id": "b", "body": "a prepaid, purpose-specific digital voucher", "body_hi": "एक प्रीपेड, प्रयोजन-विशेष डिजिटल वाउचर", "isCorrect": true}, {"id": "c", "body": "a cryptocurrency issued by NPCI", "body_hi": "NPCI द्वारा जारी एक क्रिप्टोकरेंसी", "isCorrect": false}, {"id": "d", "body": "a credit card for rural customers", "body_hi": "ग्रामीण ग्राहकों के लिए एक क्रेडिट कार्ड", "isCorrect": false}]'::jsonb,2,0.66,'e-RUPI, built by NPCI on UPI, is a voucher sent by SMS or QR code that can be redeemed only for a set purpose -- say a vaccination or a subsidy -- at a specified provider, so that the benefit reaches the intended person without cash changing hands. The similar-sounding e-rupee is the RBI''s digital currency, launched in 2022 -- the trap in this question.','UPI पर NPCI द्वारा बनाया गया ई-रूपी SMS या QR कोड से भेजा जाने वाला वाउचर है, जिसे केवल एक तय प्रयोजन, जैसे टीकाकरण या कोई सब्सिडी, के लिए किसी निर्दिष्ट सेवा-प्रदाता पर भुनाया जा सकता है, ताकि लाभ बिना नक़द लेन-देन के सही व्यक्ति तक पहुँचे। मिलते-जुलते नाम वाला ई-रुपी RBI की डिजिटल मुद्रा है, जो 2022 में शुरू हुई; यही इस प्रश्न का जाल है।','fm-e-rupi-voucher','original_pattern_matched','National Payments Corporation of India -- e-RUPI.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','mcq','medium','''UPI 123PAY'' enables:','''UPI 123PAY'' क्या संभव बनाता है?','{}'::jsonb,'[{"id": "a", "body": "payments in three foreign currencies", "body_hi": "तीन विदेशी मुद्राओं में भुगतान", "isCorrect": false}, {"id": "b", "body": "three-step verification for large RTGS transfers", "body_hi": "बड़े RTGS अंतरणों के लिए तीन-चरणीय सत्यापन", "isCorrect": false}, {"id": "c", "body": "UPI payments from feature phones", "body_hi": "फ़ीचर फ़ोन से UPI भुगतान", "isCorrect": true}, {"id": "d", "body": "instant loans of up to 1.23 lakh rupees", "body_hi": "1.23 लाख रुपये तक के तुरंत ऋण", "isCorrect": false}]'::jsonb,2,0.66,'Launched in 2022, UPI 123PAY lets users of basic phones without internet pay through options such as an interactive voice response number, missed calls and app-based functions on feature phones -- extending digital payments to people who do not own smartphones.','2022 में शुरू किया गया UPI 123PAY बिना इंटरनेट वाले साधारण फ़ोन के उपयोगकर्ताओं को इंटरैक्टिव वॉयस रिस्पॉन्स नंबर, मिस्ड कॉल और फ़ीचर फ़ोन पर ऐप-आधारित सुविधाओं जैसे विकल्पों से भुगतान करने देता है, जिससे डिजिटल भुगतान उन लोगों तक पहुँचते हैं जिनके पास स्मार्टफ़ोन नहीं है।','fm-upi-123pay','original_pattern_matched','National Payments Corporation of India -- UPI 123PAY.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','mcq','medium','The Unified Lending Interface (ULI) being developed by the RBI is meant to:','RBI द्वारा विकसित किया जा रहा एकीकृत ऋण इंटरफ़ेस (ULI) किसलिए है?','{}'::jsonb,'[{"id": "a", "body": "speed up lending by giving lenders consented access to data from many sources", "body_hi": "ऋणदाताओं को अनेक स्रोतों के डेटा तक सहमति-आधारित पहुँच देकर ऋण देना तेज़ करना", "isCorrect": true}, {"id": "b", "body": "replace all existing bank accounts with a single national account run by the RBI", "body_hi": "सभी मौजूदा बैंक खातों को RBI द्वारा चलाए जाने वाले एक ही राष्ट्रीय खाते से बदलना", "isCorrect": false}, {"id": "c", "body": "fix a common interest rate for all loans in the country", "body_hi": "देश के सभी ऋणों के लिए एक समान ब्याज दर तय करना", "isCorrect": false}, {"id": "d", "body": "allow the RBI to lend directly to households", "body_hi": "RBI को सीधे परिवारों को उधार देने देना", "isCorrect": false}]'::jsonb,2,0.66,'ULI, piloted from 2023, connects lenders to data such as land records, milk-pooling records and GST filings through standard interfaces, with the borrower''s consent, so that small farmers and MSMEs with thin credit histories can be assessed and served quickly -- aiming to do for credit what UPI did for payments.','2023 से प्रायोगिक रूप से चलाया जा रहा ULI ऋणदाताओं को मानक इंटरफ़ेस के ज़रिए, उधारकर्ता की सहमति से, भूमि अभिलेख, दुग्ध संग्रह के रिकॉर्ड और GST रिटर्न जैसे डेटा से जोड़ता है, ताकि कमज़ोर ऋण इतिहास वाले छोटे किसानों और MSME का आकलन करके उन्हें जल्दी ऋण दिया जा सके; उद्देश्य है कि ऋण के लिए वही हो जो UPI ने भुगतानों के लिए किया।','fm-unified-lending-interface','original_pattern_matched','Reserve Bank of India -- Unified Lending Interface (Reserve Bank Innovation Hub).','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','mcq','medium','The ''free-float market capitalisation'' of a company refers to:','किसी कंपनी का ''मुक्त-प्रवाह बाज़ार पूँजीकरण'' (free-float market capitalisation) किसे कहते हैं?','{}'::jsonb,'[{"id": "a", "body": "the market value of all the shares held by its promoters", "body_hi": "उसके प्रवर्तकों के पास रखे सभी शेयरों का बाज़ार मूल्य", "isCorrect": false}, {"id": "b", "body": "the face value of all the shares issued by the company since it was first listed", "body_hi": "पहली बार सूचीबद्ध होने के बाद से कंपनी द्वारा जारी सभी शेयरों का अंकित मूल्य", "isCorrect": false}, {"id": "c", "body": "the value of its assets minus its debts", "body_hi": "उसकी परिसंपत्तियों में से ऋण घटाकर बचा मूल्य", "isCorrect": false}, {"id": "d", "body": "the market value of its shares that are readily available for trading", "body_hi": "उसके उन शेयरों का बाज़ार मूल्य जो व्यापार के लिए आसानी से उपलब्ध हैं", "isCorrect": true}]'::jsonb,2,0.66,'Free-float capitalisation leaves out shares locked up with promoters, the government and other strategic holders and counts only those the public can actually trade. Index weights on the Sensex and the Nifty are based on it, so a company with a large promoter stake carries less weight than its full market value would suggest.','मुक्त-प्रवाह पूँजीकरण प्रवर्तकों, सरकार और अन्य रणनीतिक धारकों के पास बंद शेयरों को छोड़ देता है और केवल उन्हें गिनता है जिनका जनता वास्तव में व्यापार कर सकती है। सेंसेक्स और निफ़्टी पर सूचकांक भार इसी पर आधारित होते हैं, इसलिए बड़ी प्रवर्तक हिस्सेदारी वाली कंपनी का भार उसके पूरे बाज़ार मूल्य से अपेक्षित भार से कम होता है।','fm-free-float-market-cap','original_pattern_matched','BSE Limited; National Stock Exchange of India -- index methodology.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','mcq','hard','A bond with a face value of 1,000 rupees and an annual coupon of 8 per cent is trading at 800 rupees. Its current yield is:','1,000 रुपये अंकित मूल्य और 8 प्रतिशत वार्षिक कूपन वाला एक बॉन्ड 800 रुपये पर बिक रहा है। इसका वर्तमान प्रतिफल (current yield) क्या है?','{}'::jsonb,'[{"id": "a", "body": "8 per cent", "body_hi": "8 प्रतिशत", "isCorrect": false}, {"id": "b", "body": "10 per cent", "body_hi": "10 प्रतिशत", "isCorrect": true}, {"id": "c", "body": "6.4 per cent", "body_hi": "6.4 प्रतिशत", "isCorrect": false}, {"id": "d", "body": "12.5 per cent", "body_hi": "12.5 प्रतिशत", "isCorrect": false}]'::jsonb,2,0.66,'The bond pays 8 per cent of 1,000, or 80 rupees, a year. Current yield is the annual coupon divided by the market price: 80/800 = 10 per cent. The yield is above the coupon because the price has fallen below face value -- which is what happens to existing bonds when market interest rates rise.','बॉन्ड हर वर्ष 1,000 का 8 प्रतिशत, यानी 80 रुपये देता है। वर्तमान प्रतिफल वार्षिक कूपन को बाज़ार मूल्य से भाग देने पर मिलता है: 80/800 = 10 प्रतिशत। प्रतिफल कूपन से अधिक है, क्योंकि मूल्य अंकित मूल्य से नीचे गिर गया है; बाज़ार ब्याज दरें बढ़ने पर मौजूदा बॉन्डों के साथ यही होता है।','fm-current-yield-numerical','original_pattern_matched','Reserve Bank of India -- FAQs on Government Securities Market.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','mcq','hard','Credit default swaps are used mainly to:','क्रेडिट डिफ़ॉल्ट स्वैप (CDS) का उपयोग मुख्य रूप से किसलिए होता है?','{}'::jsonb,'[{"id": "a", "body": "exchange one currency for another at a fixed rate on a future date", "body_hi": "एक मुद्रा को दूसरी से भविष्य की किसी तिथि पर स्थिर दर पर बदलना", "isCorrect": false}, {"id": "b", "body": "swap fixed interest payments for floating ones", "body_hi": "स्थिर ब्याज भुगतानों को अस्थिर भुगतानों से बदलना", "isCorrect": false}, {"id": "c", "body": "transfer the risk that a borrower will default to another party", "body_hi": "किसी उधारकर्ता के चूकने के जोखिम को दूसरे पक्ष पर डालना", "isCorrect": true}, {"id": "d", "body": "convert a company''s bonds into its shares", "body_hi": "किसी कंपनी के बॉन्डों को उसके शेयरों में बदलना", "isCorrect": false}]'::jsonb,2,0.66,'In a CDS, the buyer pays a regular fee to the seller, who agrees to compensate the buyer if a named borrower defaults -- in effect insurance on a bond. CDS written on mortgage securities spread losses through the financial system in the 2008 crisis; in India the RBI permits them under its own directions. Exchanging currencies is a currency swap, and fixed-for-floating is an interest rate swap.','CDS में ख़रीदार विक्रेता को नियमित शुल्क देता है, और विक्रेता सहमत होता है कि यदि कोई नामित उधारकर्ता चूक जाए तो वह ख़रीदार की भरपाई करेगा; यह वास्तव में किसी बॉन्ड पर बीमा है। 2008 के संकट में बंधक प्रतिभूतियों पर लिखे गए CDS ने वित्तीय प्रणाली में हानियाँ फैलाईं; भारत में RBI इन्हें अपने निर्देशों के तहत अनुमति देता है। मुद्राओं की अदला-बदली मुद्रा स्वैप है, और स्थिर के बदले अस्थिर ब्याज, ब्याज दर स्वैप।','fm-credit-default-swaps','original_pattern_matched','Reserve Bank of India -- Master Direction on Credit Derivatives.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','mcq','hard','An investor buys a call option on a share with a strike price of 100 rupees, paying a premium of 5 rupees. If the share is at 120 rupees on the expiry date, the investor''s net gain per share is:','एक निवेशक किसी शेयर पर 100 रुपये के स्ट्राइक मूल्य वाला कॉल विकल्प 5 रुपये का प्रीमियम देकर ख़रीदता है। यदि समाप्ति तिथि पर शेयर का मूल्य 120 रुपये है, तो निवेशक का प्रति शेयर शुद्ध लाभ कितना है?','{}'::jsonb,'[{"id": "a", "body": "15 rupees", "body_hi": "15 रुपये", "isCorrect": true}, {"id": "b", "body": "20 rupees", "body_hi": "20 रुपये", "isCorrect": false}, {"id": "c", "body": "25 rupees", "body_hi": "25 रुपये", "isCorrect": false}, {"id": "d", "body": "5 rupees", "body_hi": "5 रुपये", "isCorrect": false}]'::jsonb,2,0.66,'A call gives the right to buy at the strike price. At expiry the option is worth 120 - 100 = 20 rupees; after subtracting the 5-rupee premium, the net gain is 15 rupees. Had the share ended below 100, the investor would let the option lapse and lose only the premium.','कॉल विकल्प स्ट्राइक मूल्य पर ख़रीदने का अधिकार देता है। समाप्ति पर विकल्प का मूल्य 120 - 100 = 20 रुपये है; 5 रुपये का प्रीमियम घटाने पर शुद्ध लाभ 15 रुपये है। यदि शेयर 100 से नीचे रहता, तो निवेशक विकल्प को छोड़ देता और केवल प्रीमियम गँवाता।','fm-call-option-numerical','original_pattern_matched','Securities and Exchange Board of India -- Investor education on derivatives.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','mcq','easy','An ''IPO'' refers to:','''IPO'' किसे कहते हैं?','{}'::jsonb,'[{"id": "a", "body": "a loan given by the RBI to a company", "body_hi": "RBI द्वारा किसी कंपनी को दिया गया ऋण", "isCorrect": false}, {"id": "b", "body": "an investment by the government in a public sector bank", "body_hi": "किसी सार्वजनिक क्षेत्र के बैंक में सरकार द्वारा निवेश", "isCorrect": false}, {"id": "c", "body": "an insurance policy on a company''s property", "body_hi": "किसी कंपनी की संपत्ति पर बीमा पॉलिसी", "isCorrect": false}, {"id": "d", "body": "a company''s first sale of shares to the public", "body_hi": "किसी कंपनी द्वारा जनता को पहली बार शेयर बेचना", "isCorrect": true}]'::jsonb,2,0.66,'In an initial public offering a company offers its shares to the public for the first time and then lists them on a stock exchange; later sales of new shares by a listed company are follow-on public offers.','प्रारंभिक सार्वजनिक निर्गम (IPO) में कोई कंपनी पहली बार अपने शेयर जनता को देती है और फिर उन्हें स्टॉक एक्सचेंज पर सूचीबद्ध कराती है; सूचीबद्ध कंपनी द्वारा बाद में नए शेयरों की बिक्री को फ़ॉलो-ऑन सार्वजनिक निर्गम (FPO) कहते हैं।','fm-ipo-meaning-easy','original_pattern_matched','NCERT Class XII, Business Studies -- Financial Markets.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','mcq','easy','A ''dividend'' is:','''लाभांश'' (dividend) क्या है?','{}'::jsonb,'[{"id": "a", "body": "the interest paid by a bank on a fixed deposit at maturity", "body_hi": "परिपक्वता पर किसी बैंक द्वारा सावधि जमा पर दिया जाने वाला ब्याज", "isCorrect": false}, {"id": "b", "body": "a share of a company''s profit paid to its shareholders", "body_hi": "किसी कंपनी के लाभ का वह भाग जो उसके शेयरधारकों को दिया जाता है", "isCorrect": true}, {"id": "c", "body": "a tax paid by companies on their profits", "body_hi": "कंपनियों द्वारा अपने लाभ पर दिया जाने वाला कर", "isCorrect": false}, {"id": "d", "body": "the fee charged by a broker for a trade", "body_hi": "किसी सौदे के लिए ब्रोकर द्वारा लिया जाने वाला शुल्क", "isCorrect": false}]'::jsonb,2,0.66,'When a company earns a profit, its board may distribute part of it to shareholders as a dividend and keep the rest to reinvest; unlike interest on a deposit or a bond, a dividend is not promised and can be cut or skipped.','जब कोई कंपनी लाभ कमाती है, तो उसका बोर्ड उसका एक भाग लाभांश के रूप में शेयरधारकों में बाँट सकता है और शेष को फिर से निवेश के लिए रख सकता है; जमा या बॉन्ड पर ब्याज के विपरीत, लाभांश का वादा नहीं होता और उसे घटाया या छोड़ा जा सकता है।','fm-dividend-easy','original_pattern_matched','NCERT Class XII, Business Studies -- Financial Markets.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Investors often buy gold during financial crises.", "assertion_hi": "वित्तीय संकटों के समय निवेशक प्रायः सोना ख़रीदते हैं।", "reason": "Gold is seen as a store of value when confidence in financial assets falls.", "reason_hi": "जब वित्तीय परिसंपत्तियों पर भरोसा घटता है, तो सोने को मूल्य-संचय (store of value) के रूप में देखा जाता है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct and Statement-II explains Statement-I. Gold is no one''s liability -- it cannot default and is not printed by any government -- so in crises, wars and bouts of inflation investors and central banks turn to it, and its price usually rises.','दोनों कथन सही हैं और कथन-II कथन-I की व्याख्या करता है। सोना किसी की देयता नहीं है; यह चूक नहीं सकता और कोई सरकार इसे छापती नहीं; इसलिए संकटों, युद्धों और मुद्रास्फीति के दौरों में निवेशक और केंद्रीय बैंक इसकी ओर जाते हैं, और इसकी क़ीमत प्रायः बढ़ती है।','fm-gold-safe-haven','original_pattern_matched','Reserve Bank of India -- Annual Report (foreign exchange reserves management).','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Insurance penetration in India is lower than the world average.", "assertion_hi": "भारत में बीमा पैठ (insurance penetration) विश्व औसत से कम है।", "reason": "India''s first life insurance company was set up in Calcutta in 1818.", "reason_hi": "भारत की पहली जीवन बीमा कंपनी 1818 में कलकत्ता में स्थापित हुई।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": true}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct, but Statement-II does not explain Statement-I. Premiums in India are around 4 per cent of GDP against about 7 per cent worldwide, mainly because incomes are low, awareness is limited and many policies are bought as tax-saving investments rather than for protection. The Oriental Life Insurance Company of 1818 is a fact of history that says nothing about why coverage is low today.','दोनों कथन सही हैं, पर कथन-II कथन-I की व्याख्या नहीं करता। भारत में प्रीमियम GDP का लगभग 4 प्रतिशत है, जबकि विश्व में लगभग 7 प्रतिशत; मुख्य कारण हैं कम आय, सीमित जागरूकता और यह कि कई पॉलिसियाँ सुरक्षा के बजाय कर बचाने वाले निवेश के रूप में ख़रीदी जाती हैं। 1818 की ओरिएंटल लाइफ़ इंश्योरेंस कंपनी इतिहास का एक तथ्य है, जो यह नहीं बताता कि आज बीमा का दायरा कम क्यों है।','fm-insurance-penetration','original_pattern_matched','Insurance Regulatory and Development Authority of India -- Annual Report.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "UPI payments can be made at any hour on any day.", "assertion_hi": "UPI भुगतान किसी भी दिन, किसी भी समय किए जा सकते हैं।", "reason": "UPI transactions are settled between banks one by one through RTGS as each payment is made.", "reason_hi": "UPI लेन-देन का निपटान हर भुगतान के साथ RTGS के ज़रिए बैंकों के बीच एक-एक करके होता है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": true}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Statement-I is correct but Statement-II is incorrect. The customer sees money move instantly because the banks credit and debit accounts in real time, but the inter-bank settlement is done later in batches, several times a day, on a net basis through NPCI and the RBI''s systems.','कथन-I सही है पर कथन-II गलत है। ग्राहक को पैसा तुरंत जाता दिखता है, क्योंकि बैंक वास्तविक समय में खाते जमा और नामे करते हैं, पर अंतर-बैंक निपटान बाद में, दिन में कई बार, बैचों में, शुद्ध आधार पर NPCI और RBI की प्रणालियों के ज़रिए होता है।','fm-upi-settlement','original_pattern_matched','National Payments Corporation of India -- UPI settlement process.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "The retail e-rupee earns interest like a savings deposit.", "assertion_hi": "खुदरा ई-रुपी पर बचत जमा की तरह ब्याज मिलता है।", "reason": "The e-rupee is a direct liability of the RBI.", "reason_hi": "ई-रुपी RBI की सीधी देयता है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": true}]'::jsonb,2,0.66,'Statement-I is incorrect but Statement-II is correct. Like a currency note, the e-rupee is a claim on the central bank and pays no interest; if it paid interest, people might move money out of bank deposits, weakening banks'' ability to lend.','कथन-I गलत है पर कथन-II सही है। करेंसी नोट की तरह ई-रुपी केंद्रीय बैंक पर एक दावा है और इस पर कोई ब्याज नहीं मिलता; यदि इस पर ब्याज मिलता, तो लोग बैंक जमाओं से पैसा निकाल सकते थे, जिससे बैंकों की उधार देने की क्षमता कमज़ोर होती।','fm-erupee-no-interest','original_pattern_matched','Reserve Bank of India -- Concept Note on Central Bank Digital Currency (2022).','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Insurance companies can pay large claims while charging each policyholder a small premium.", "assertion_hi": "बीमा कंपनियाँ हर पॉलिसीधारक से छोटा प्रीमियम लेकर भी बड़े दावों का भुगतान कर सकती हैं।", "reason": "Only a small share of policyholders suffer an insured loss in any given year.", "reason_hi": "किसी भी वर्ष में पॉलिसीधारकों के केवल एक छोटे भाग को ही बीमित हानि होती है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct and Statement-II explains Statement-I. By pooling the premiums of many people facing similar but independent risks, the insurer uses the law of large numbers: the contributions of the many pay for the losses of the few.','दोनों कथन सही हैं और कथन-II कथन-I की व्याख्या करता है। समान पर स्वतंत्र जोखिमों वाले बहुत-से लोगों के प्रीमियम एकत्र करके बीमाकर्ता बड़ी संख्याओं के नियम का उपयोग करता है: अनेक लोगों का अंशदान कुछ लोगों की हानि का भुगतान करता है।','fm-insurance-risk-pooling','original_pattern_matched','Insurance Regulatory and Development Authority of India -- Policyholder education.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Card payments have grown rapidly in India in recent years.", "assertion_hi": "हाल के वर्षों में भारत में कार्ड भुगतान तेज़ी से बढ़े हैं।", "reason": "Card networks such as RuPay, Visa and Mastercard are authorised by the RBI under the Payment and Settlement Systems Act, 2007.", "reason_hi": "रुपे, वीज़ा और मास्टरकार्ड जैसे कार्ड नेटवर्क भुगतान और निपटान प्रणाली अधिनियम, 2007 के तहत RBI द्वारा अधिकृत हैं।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": true}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct, but Statement-II does not explain Statement-I. Card use has grown with rising incomes, e-commerce and the spread of payment terminals; the fact that the networks need RBI authorisation describes how they are regulated, not why their use has grown.','दोनों कथन सही हैं, पर कथन-II कथन-I की व्याख्या नहीं करता। बढ़ती आय, ई-कॉमर्स और भुगतान टर्मिनलों के प्रसार के साथ कार्ड का उपयोग बढ़ा है; नेटवर्कों को RBI से अधिकार-पत्र चाहिए, यह बताता है कि उनका विनियमन कैसे होता है, यह नहीं कि उनका उपयोग क्यों बढ़ा।','fm-card-payments-pss-act','original_pattern_matched','Payment and Settlement Systems Act, 2007.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','assertion_reason','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Digital payments reduce the need to carry cash.", "assertion_hi": "डिजिटल भुगतान नक़दी साथ रखने की आवश्यकता घटाते हैं।", "reason": "Digital payments move money electronically from one account to another.", "reason_hi": "डिजिटल भुगतान पैसे को इलेक्ट्रॉनिक रूप से एक खाते से दूसरे खाते में भेजते हैं।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct and Statement-II explains Statement-I. Because the money moves between accounts, a phone or card can take the place of notes for everyday purchases.','दोनों कथन सही हैं और कथन-II कथन-I की व्याख्या करता है। चूँकि पैसा खातों के बीच जाता है, इसलिए रोज़मर्रा की ख़रीदारी में फ़ोन या कार्ड नोटों की जगह ले सकते हैं।','fm-digital-payments-cash-easy','original_pattern_matched','Reserve Bank of India -- Financial Education.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','assertion_reason','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Shares of listed companies can be bought and sold on stock exchanges.", "assertion_hi": "सूचीबद्ध कंपनियों के शेयर स्टॉक एक्सचेंजों पर ख़रीदे और बेचे जा सकते हैं।", "reason": "Only the government can buy shares of listed companies.", "reason_hi": "सूचीबद्ध कंपनियों के शेयर केवल सरकार ख़रीद सकती है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": true}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Statement-I is correct but Statement-II is incorrect. Any individual or institution with a demat and trading account can buy listed shares; more than ten crore Indians now hold such accounts.','कथन-I सही है पर कथन-II गलत है। डीमैट और ट्रेडिंग खाते वाला कोई भी व्यक्ति या संस्था सूचीबद्ध शेयर ख़रीद सकती है; अब दस करोड़ से अधिक भारतीयों के पास ऐसे खाते हैं।','fm-stock-exchange-trading-easy','original_pattern_matched','Securities and Exchange Board of India -- Investor education.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','assertion_reason','hard','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Heavy selling by foreign portfolio investors can weaken the rupee.", "assertion_hi": "विदेशी पोर्टफ़ोलियो निवेशकों द्वारा भारी बिकवाली रुपये को कमज़ोर कर सकती है।", "reason": "Foreign portfolio investors must register with SEBI before investing in Indian securities.", "reason_hi": "भारतीय प्रतिभूतियों में निवेश से पहले विदेशी पोर्टफ़ोलियो निवेशकों को SEBI के पास पंजीकरण कराना होता है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": true}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct, but Statement-II does not explain Statement-I. When FPIs sell Indian shares and bonds, they convert the rupees into dollars to take the money out, which raises demand for dollars and pushes the rupee down unless the RBI sells dollars from its reserves. The registration rule is a regulatory fact, not the cause.','दोनों कथन सही हैं, पर कथन-II कथन-I की व्याख्या नहीं करता। जब FPI भारतीय शेयर और बॉन्ड बेचते हैं, तो पैसा बाहर ले जाने के लिए रुपयों को डॉलरों में बदलते हैं, जिससे डॉलर की माँग बढ़ती है और रुपया नीचे जाता है, जब तक RBI अपने भंडार से डॉलर न बेचे। पंजीकरण का नियम एक विनियामक तथ्य है, कारण नहीं।','fm-fpi-outflows-rupee','original_pattern_matched','Securities and Exchange Board of India (Foreign Portfolio Investors) Regulations, 2019.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','assertion_reason','hard','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Government bond yields in India tend to rise when the government''s borrowing programme turns out larger than expected.", "assertion_hi": "जब सरकार का उधार कार्यक्रम अपेक्षा से बड़ा निकलता है, तो भारत में सरकारी बॉन्डों का प्रतिफल बढ़ने लगता है।", "reason": "A larger supply of government bonds pushes their prices down.", "reason_hi": "सरकारी बॉन्डों की अधिक आपूर्ति उनकी क़ीमतों को नीचे धकेलती है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true, "reason_2": "Bond prices and bond yields move in opposite directions.", "reason_2_hi": "बॉन्ड की क़ीमतें और बॉन्ड प्रतिफल विपरीत दिशाओं में चलते हैं।"}'::jsonb,'[{"id": "a", "body": "Both Statement II and Statement III are correct and both of them explain Statement I", "body_hi": "कथन-II और कथन-III दोनों सही हैं और ये दोनों कथन-I की व्याख्या करते हैं", "isCorrect": true}, {"id": "b", "body": "Both Statement II and Statement III are correct but only one of them explains Statement I", "body_hi": "कथन-II और कथन-III दोनों सही हैं, किंतु इनमें से केवल एक ही कथन-I की व्याख्या करता है", "isCorrect": false}, {"id": "c", "body": "Only one of the Statements II and III is correct and that explains Statement I", "body_hi": "कथन-II और कथन-III में से केवल एक सही है और वही कथन-I की व्याख्या करता है", "isCorrect": false}, {"id": "d", "body": "Neither Statement II nor Statement III is correct", "body_hi": "न तो कथन-II सही है, न ही कथन-III", "isCorrect": false}]'::jsonb,2,0.66,'Both Statements II and III are correct, and both explain Statement I. More bonds must be sold to the same pool of banks, insurers and funds, so they can be sold only at lower prices; and since a bond''s fixed coupon is spread over a lower price, a lower price means a higher yield. This is why budget-day borrowing numbers move the bond market.','कथन II और III दोनों सही हैं, और दोनों कथन I की व्याख्या करते हैं। अधिक बॉन्ड बैंकों, बीमा कंपनियों और फ़ंडों के उसी समूह को बेचने होते हैं, इसलिए वे केवल कम क़ीमतों पर बिक सकते हैं; और चूँकि बॉन्ड का स्थिर कूपन कम क़ीमत पर बँटता है, कम क़ीमत का अर्थ है ऊँचा प्रतिफल। इसीलिए बजट के दिन घोषित उधार के आँकड़े बॉन्ड बाज़ार को हिला देते हैं।','fm-borrowing-bond-yields','original_pattern_matched','Reserve Bank of India -- Financial Stability Report.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','match_the_following','medium','Consider the following pairs of instruments and the markets in which they are traded:','उपकरणों और उन बाज़ारों के निम्नलिखित युग्मों पर विचार कीजिए जिनमें उनका व्यापार होता है:','{"list_1": ["1. Debentures", "2. Currency swaps", "3. Warehouse receipts", "4. Repo"], "list_1_hi": ["1. डिबेंचर", "2. मुद्रा स्वैप", "3. गोदाम रसीदें", "4. रेपो"], "list_2": ["Capital market", "Foreign exchange market", "Commodity market", "Capital market"], "list_2_hi": ["पूँजी बाज़ार", "विदेशी मुद्रा बाज़ार", "कमोडिटी बाज़ार", "पूँजी बाज़ार"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": true}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb,2,0.66,'Pairs 1, 2 and 3 are correct: debentures are long-term debt of companies, currency swaps exchange flows in two currencies, and electronic warehouse receipts back delivery and financing in commodity markets. Pair 4 is wrong: a repo -- a short-term loan against securities that the borrower agrees to buy back -- belongs to the money market, usually for a day to a few weeks.','युग्म 1, 2 और 3 सही हैं: डिबेंचर कंपनियों का दीर्घकालिक ऋण हैं, मुद्रा स्वैप दो मुद्राओं में प्रवाहों की अदला-बदली करते हैं, और इलेक्ट्रॉनिक गोदाम रसीदें कमोडिटी बाज़ारों में डिलीवरी और वित्तपोषण का आधार होती हैं। युग्म 4 गलत है: रेपो, यानी प्रतिभूतियों के बदले ऐसा अल्पकालिक ऋण जिनको उधारकर्ता वापस ख़रीदने पर सहमत होता है, मुद्रा बाज़ार का भाग है, सामान्यतः एक दिन से कुछ सप्ताहों के लिए।','fm-instruments-markets-pairs','original_pattern_matched','Reserve Bank of India -- Master Directions on Money Market Instruments; Securities and Exchange Board of India.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','match_the_following','hard','Consider the following pairs of types of bonds and their features:','बॉन्डों के प्रकारों और उनकी विशेषताओं के निम्नलिखित युग्मों पर विचार कीजिए:','{"list_1": ["1. Perpetual bond", "2. Convertible bond", "3. Sovereign green bond", "4. Callable bond"], "list_1_hi": ["1. स्थायी (perpetual) बॉन्ड", "2. परिवर्तनीय बॉन्ड", "3. सॉवरेन ग्रीन बॉन्ड", "4. कॉल करने योग्य (callable) बॉन्ड"], "list_2": ["Has no maturity date", "Can be turned into equity shares", "Funds only defence projects", "The holder can demand early repayment"], "list_2_hi": ["कोई परिपक्वता तिथि नहीं", "इक्विटी शेयरों में बदला जा सकता है", "केवल रक्षा परियोजनाओं का वित्तपोषण", "धारक समय से पहले भुगतान माँग सकता है"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": true}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": false}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb,2,0.66,'Pairs 1 and 2 are correct. Pair 3 is wrong: sovereign green bonds fund public projects that reduce emissions or help adapt to climate change -- solar and wind power, clean transport, afforestation -- not defence. Pair 4 is wrong: a callable bond lets the issuer repay early, usually when interest rates have fallen; a bond that lets the holder demand early repayment is a puttable bond.','युग्म 1 और 2 सही हैं। युग्म 3 गलत है: सॉवरेन ग्रीन बॉन्ड उन सार्वजनिक परियोजनाओं का वित्तपोषण करते हैं जो उत्सर्जन घटाती हैं या जलवायु परिवर्तन से अनुकूलन में मदद करती हैं, जैसे सौर और पवन ऊर्जा, स्वच्छ परिवहन और वनीकरण, रक्षा का नहीं। युग्म 4 गलत है: कॉल करने योग्य बॉन्ड जारीकर्ता को समय से पहले भुगतान करने देता है, सामान्यतः तब जब ब्याज दरें गिर गई हों; धारक को समय से पहले भुगतान माँगने देने वाला बॉन्ड पुट करने योग्य (puttable) बॉन्ड है।','fm-bond-types-pairs','original_pattern_matched','Ministry of Finance -- Sovereign Green Bonds Framework (2022); Securities and Exchange Board of India.','draft')
